    except Exception as e:
        results["R2"] = {"status": "error", "value": None, "method": "", "criteria": [], "note": str(e)}

    # R3: No intersection with phone volume (Improved sampling)
    try:
        samples_a = 25
        samples_b = 10
        samples_y = 20
        test_points = []
        for a in np.linspace(0, 160, samples_a):
            for b in np.linspace(0, 9, samples_b):
                for y in np.linspace(-37.5, 37.5, samples_y):
                    p = np.array([0, y, 8]) + a * U + b * N
                    test_points.append(p)
        pts = np.array(test_points)
        inside = mesh.contains(pts)
        intersections = int(np.sum(inside))
        is_ok = (intersections == 0)
        results["R3"] = {
            "status": "pass" if is_ok else "fail",
            "value": intersections,
            "method": f"Checked {len(pts)} sample points within phone volume for intersection with stand mesh.",
            "criteria": [{"condition": "Must not intersect the phone volume", "measured": intersections, "ok": is_ok}],
            "note": ""
        }
    except Exception as e:
        results["R3"] = {"status": "error", "value": None, "method": "", "criteria": [], "note": str(e)}

    # R4 & R5 helper: Verify material continuity/coverage in a region.
    # Instead of just checking if ANY point is inside (presence), we check the fraction 
    # to ensure it's a substantial feature, not just a stray voxel.
    def check_region_density(a_range, b_range, y_range, density_threshold=0.5):
        pts_list = []
        # Higher resolution for checking features
        for a in np.linspace(a_range[0], a_range[1], 12):
            for b in np.linspace(b_range[0], b_range[1], 8):
                for y in np.linspace(y_range[0], y_range[1], 8):
                    p = np.array([0, y, 8]) + a * U + b * N
                    pts_list.append(p)
        if not pts_list: return False, 0.0
